  "guide/pillar-gap-ja": {
    "eyebrow": "दिन स्तंभ",
    "title": "甲子 दिन स्तंभ",
    "summary": "Saju-Link दिन स्तंभ 甲子 को कैसे पढ़ता है — दिन की शाखा द्वारा धारण किए गए तने दिन तने के लिए क्या हैं — ठीक वैसे ही जैसे इसके गणना नियमों में है।",
    "backLabel": "गणना का आधार",
    "sections": [
      {
        "title": "甲子 साठ वर्ष के चक्र का दिन स्तंभ क्रमांक 1 है",
        "blocks": [
          {
            "p": "जब जन्म के दिन का तना-शाखा 甲子 हो, तो दिन तना 甲 (काष्ठ, यांग) है और दिन की शाखा 子 (चूहा) है। साठ वर्ष के चक्र में यह संयोजन क्रमांक 1 है।"
          },
          {
            "p": "Saju-Link उस व्यक्ति को \"यांग काष्ठ (甲)\" कहता है जिसका दिन तना 甲 है, और परिणाम स्क्रीन जो पंक्ति दिखाती है वह यह है: \"सीधा बढ़ता ऊँचा पेड़। दिशा तय हो जाए तो डगमगाता नहीं, और झुकने से बेहतर सह लेना चुनता है।\" इस पंक्ति का नीचे की व्याख्या या अंकों से कोई संबंध नहीं है।"
          }
        ]
      },
      {
        "title": "दिन की शाखा 子 द्वारा धारण किए गए तने दिन तने के लिए क्या हैं",
        "blocks": [
          {
            "p": "दिन की शाखा जीवनसाथी की स्थिति है। दिन तना 甲 से पढ़ने पर 子 द्वारा धारण किए गए तने इस प्रकार हैं। प्रमुख तना (癸) शाखा की प्रतिनिधि ऊर्जा है।"
          },
          {
            "table": {
              "caption": "甲子 की दिन की शाखा के छिपे हुए तने",
              "head": [
                "छिपा हुआ तना",
                "स्थिति",
                "हिस्सा",
                "दिन तना 甲 के लिए"
              ],
              "rows": [
                [
                  "यांग जल (壬)",
                  "शेष (餘氣)",
                  "{hidJaYeo}",
                  "अनोखा सहारा (偏印)"
                ],
                [
                  "यिन जल (癸)",
                  "प्रमुख (本氣)",
                  "{hidJaBon}",
                  "पालन (正印)"
                ]
              ]
            }
          }
        ]
      },
      {
        "title": "जीवनसाथी की स्थिति और यह दिन स्तंभ",
        "blocks": [
          {
            "p": "पारंपरिक myeongri जीवनसाथी की स्थिति को पुरुषों के लिए स्थिर धन (正財) और महिलाओं के लिए अधिकार (正官) के रूप में पढ़ता है। 甲 को दिन तना मानने पर स्थिर धन 己 है और अधिकार 辛 है।"
          },
          {
            "p": "पुरुषों के लिए जीवनसाथी की स्थिति (स्थिर धन) 己 है। 己 子 के भीतर धारण नहीं किया गया है।"
          },
          {
            "p": "महिलाओं के लिए जीवनसाथी की स्थिति (अधिकार) 辛 है। 辛 子 के भीतर धारण नहीं किया गया है।"
          }
        ]
      },
      {
        "title": "पड़ोसी दिन स्तंभ और वे अक्षर जिनसे यह बना है",
        "blocks": [
          {
            "p": "साठ वर्ष के चक्र में पिछला दिन स्तंभ [癸亥](/guide/pillar-gye-hae) है और अगला [乙丑](/guide/pillar-eul-chuk) है।"
          },
          {
            "p": "यह [यांग काष्ठ (甲)](/guide/stem-gap) और [子 (चूहा)](/guide/branch-ja) से बना है।"
          }
        ]
      },
      {
        "kind": "note",
        "title": "यह गाइड क्या नहीं कहता",
        "blocks": [
          {
            "ul": [
              "एक दिन स्तंभ किसी व्यक्ति या संबंध का निर्णय नहीं करता। saju को चार स्तंभों के आठ अक्षरों के आपसी संबंध से पढ़ा जाता है।",
              "जीवनसाथी की स्थिति की व्याख्या पारंपरिक myeongri का एक नियम आगे ले जाती है, और यदि आप अपना लिंग नहीं बताते तो यह स्थिति नहीं पढ़ी जाती।"
            ]
          }
        ]
      }
    ]
  },

