            "p": "पारंपरिक myeongri जीवनसाथी की स्थिति को पुरुषों के लिए स्थिर धन (正財) और महिलाओं के लिए अधिकार (正官) के रूप में पढ़ता है। 辛 को दिन तना मानने पर स्थिर धन 甲 है और अधिकार 丙 है।"
