            "p": "Saju-Link उस व्यक्ति को \"यांग काष्ठ (甲)\" कहता है जिसका दिन तना 甲 है, और परिणाम स्क्रीन जो पंक्ति दिखाती है वह यह है: \"सीधा बढ़ता ऊँचा पेड़। दिशा तय हो जाए तो डगमगाता नहीं, और झुकने से बेहतर सह लेना चुनता है।\" इस पंक्ति का नीचे की व्याख्या या अंकों से कोई संबंध नहीं है।"
