            "p": "यदि आप ऐसा करते हैं, तो संतुलन तत्व को उत्पन्न करने वाली ऊर्जा और संतुलन तत्व को दबाने वाली ऊर्जा दोनों बुरी हो जाती हैं, और ऊपर की तालिका में अंतिम दो पंक्तियाँ अदृश्य हो जाती हैं। केवल वह ऊर्जा जो **विपरीत दिशा में अधिक दबाव डालती है** को दबाने और समर्थन के अर्थ के अनुसार विपरीत तत्व के रूप में देखा जाता है।"
