        "परिणाम स्क्रीन और रिपोर्ट के नीचे, गणना मानदंड (जैसे, sajulink-natal-v1) निर्दिष्ट किए गए हैं। यदि इनपुट समान है, तो समान मान हमेशा समान मानदंड के तहत निकलेंगे।",
        "यदि myeongri की व्याख्या के नियमों में परिवर्तन होता है और स्कोर भिन्न हो सकते हैं, तो हम पहले इस तथ्य और प्रभावी तिथि को यहाँ पोस्ट करेंगे। इसका कारण यह है कि आपके द्वारा पहले प्राप्त परिणाम लिंक में संख्याएँ बदल सकती हैं।",
        "वर्तमान मानदंड v10 है, और भुगतान अभी भी तैयारी में है।"
